package br.com.sussmartcare.presence.application;
import br.com.sussmartcare.presence.domain.*; import br.com.sussmartcare.presence.infrastructure.*; import br.com.sussmartcare.presence.infrastructure.outbox.EventOutbox; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class PresenceApplicationService { private final PresenceEventRepository repo; private final EventOutbox outbox; public PresenceApplicationService(PresenceEventRepository r,EventOutbox o){repo=r;outbox=o;} @Transactional public PresenceEvent record(UUID visit,UUID patient,String type,String zone,String source,Instant at){var e=repo.save(new PresenceEvent(visit,patient,type,zone,source,at));outbox.append("patient-presence-changed",visit.toString(),new PresenceChanged(visit,patient,type,zone,source,e.getOccurredAt()));return e;} public List<PresenceEvent> history(UUID visit){return repo.findByVisitIdOrderByOccurredAtAsc(visit);} public record PresenceChanged(UUID visitId,UUID patientId,String eventType,String zoneId,String source,Instant occurredAt){} }
